// computation kernel
// imgIn, imgOut, y1, y2: i x j
[[gnu::flatten, gnu::noinline]]
void kernel_deriche(num_t alpha, auto imgIn, auto imgOut, auto y1, auto y2) {
	using namespace noarr;

	num_t k;
	num_t a1, a2, a3, a4, a5, a6, a7, a8;
	num_t b1, b2, c1, c2;

#pragma scop
	// -------------------------------------------------------------------------
	// Coefficient setup (same mathematics as original C version)
	// -------------------------------------------------------------------------
	const num_t one  = SCALAR_VAL(1.0);
	const num_t two  = SCALAR_VAL(2.0);
	const num_t zero = SCALAR_VAL(0.0);

	// Reuse exponentials instead of recomputing them many times
	const num_t exp_neg_alpha  = EXP_FUN(-alpha);
	const num_t exp_pos_2alpha = EXP_FUN(SCALAR_VAL(2.0) * alpha);
	const num_t exp_neg_2alpha = EXP_FUN(SCALAR_VAL(-2.0) * alpha);

	k  = (one - exp_neg_alpha) * (one - exp_neg_alpha)
	   / (one + two * alpha * exp_neg_alpha - exp_pos_2alpha);

	a1 = a5 = k;
	a2 = a6 = k * exp_neg_alpha * (alpha - one);
	a3 = a7 = k * exp_neg_alpha * (alpha + one);
	a4 = a8 = -k * exp_neg_2alpha;

	b1 = POW_FUN(two, -alpha);
	b2 = -exp_neg_2alpha;

	c1 = c2 = one;

	// lengths used for reverse traversals
	const std::size_t w_len = imgIn | get_length<'i'>(); // W
	const std::size_t h_len = imgIn | get_length<'j'>(); // H

	// -------------------------------------------------------------------------
	// 1st pass: causal filter along j, for each i (forward j)
	//
	// for (i=0; i<W; i++)
	//   ym1=0; ym2=0; xm1=0;
	//   for (j=0; j<H; j++)
	//     y1[i][j] = a1*imgIn[i][j] + a2*xm1 + b1*ym1 + b2*ym2; ...
	//
	// We parallelize across rows (dimension 'i') and keep the inner
	// j-loop contiguous for good cache locality.
	// -------------------------------------------------------------------------
	{
		auto trav_rows = traverser(y1, imgIn); // outermost dimension is 'i'

		#pragma omp parallel for
		for (auto row_trav : trav_rows) { // each iteration handles a single i
			num_t ym1 = zero;
			num_t ym2 = zero;
			num_t xm1 = zero;

			// Traverse j in increasing order: 0 .. H-1
			row_trav.template for_each<'j'>([&](auto state) {
				const num_t x = imgIn[state];
				const num_t y = a1 * x + a2 * xm1 + b1 * ym1 + b2 * ym2;

				y1[state] = y;

				// Update recurrence state
				xm1 = x;
				ym2 = ym1;
				ym1 = y;
			});
		}
	}

	// -------------------------------------------------------------------------
	// 2nd pass: anti-causal filter along j, for each i (reverse j)
	//
	// Original C: for (j=H-1; j>=0; j--)
	// Here we iterate j in 0..H-1 but internally map to j_rev = H-1-j.
	// We again parallelize across rows (dimension 'i').
	// -------------------------------------------------------------------------
	{
		auto trav_rows = traverser(y2, imgIn); // outermost dimension is 'i'

		#pragma omp parallel for
		for (auto row_trav : trav_rows) {
			num_t yp1 = zero;
			num_t yp2 = zero;
			num_t xp1 = zero;
			num_t xp2 = zero;

			// Only 'i' is fixed in this state; 'j' will be added below.
			auto base_state = row_trav.state();

			// j_rev will run H-1, H-2, ..., 0
			std::size_t j_rev = h_len;

			row_trav.template for_each<'j'>([&](auto /*unused*/) {
				--j_rev; // first iteration: j_rev = H-1

				auto rev_state = base_state + idx<'j'>(j_rev);

				const num_t y = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;
				y2[rev_state] = y;

				// Update recurrence state
				xp2 = xp1;
				xp1 = imgIn[rev_state];
				yp2 = yp1;
				yp1 = y;
			});
		}
	}

	// -------------------------------------------------------------------------
	// Combine vertical passes:
	// imgOut[i][j] = c1 * (y1[i][j] + y2[i][j]);
	// Element-wise, so we can parallelize freely.
	// -------------------------------------------------------------------------
	{
		auto trav = traverser(imgOut, y1, y2);

		#pragma omp parallel for
		for (auto sub_trav : trav) {
			sub_trav.for_each([&](auto state) {
				imgOut[state] = c1 * (y1[state] + y2[state]);
			});
		}
	}

	// -------------------------------------------------------------------------
	// 3rd pass: causal filter along i, for each j (forward i)
	//
	// for (j=0; j<H; j++)
	//   tm1=0; ym1=0; ym2=0;
	//   for (i=0; i<W; i++)
	//     y1[i][j] = a5*imgOut[i][j] + a6*tm1 + b1*ym1 + b2*ym2; ...
	//
	// We hoist 'j' to be the outer dimension and parallelize over columns.
	// Inner dimension 'i' is strided but unavoidable for this layout.
	// -------------------------------------------------------------------------
	{
		auto trav_cols = traverser(y1, imgOut).order(hoist<'j'>());

		#pragma omp parallel for
		for (auto col_trav : trav_cols) { // each iteration handles a single j
			num_t tm1 = zero;
			num_t ym1 = zero;
			num_t ym2 = zero;

			// Traverse i in increasing order: 0 .. W-1
			col_trav.template for_each<'i'>([&](auto state) {
				const num_t x = imgOut[state];
				const num_t y = a5 * x + a6 * tm1 + b1 * ym1 + b2 * ym2;

				y1[state] = y;

				// Update recurrence state
				tm1 = x;
				ym2 = ym1;
				ym1 = y;
			});
		}
	}

	// -------------------------------------------------------------------------
	// 4th pass: anti-causal filter along i, for each j (reverse i)
	//
	// Original C: for (i=W-1; i>=0; i--)
	// We again iterate i in 0..W-1 but map to i_rev = W-1-i.
	// We parallelize across columns (dimension 'j').
	// -------------------------------------------------------------------------
	{
		auto trav_cols = traverser(y2, imgOut).order(hoist<'j'>());

		#pragma omp parallel for
		for (auto col_trav : trav_cols) {
			num_t tp1 = zero;
			num_t tp2 = zero;
			num_t yp1 = zero;
			num_t yp2 = zero;

			// Only 'j' is fixed; 'i' will be added below.
			auto base_state = col_trav.state();

			// i_rev will run W-1, W-2, ..., 0
			std::size_t i_rev = w_len;

			col_trav.template for_each<'i'>([&](auto /*unused*/) {
				--i_rev; // first iteration: i_rev = W-1

				auto rev_state = base_state + idx<'i'>(i_rev);

				const num_t y = a7 * tp1 + a8 * tp2 + b1 * yp1 + b2 * yp2;
				y2[rev_state] = y;

				// Update recurrence state
				tp2 = tp1;
				tp1 = imgOut[rev_state];
				yp2 = yp1;
				yp1 = y;
			});
		}
	}

	// -------------------------------------------------------------------------
	// Final combine:
	// imgOut[i][j] = c2 * (y1[i][j] + y2[i][j]);
	// Again purely element-wise and therefore fully parallelizable.
	// -------------------------------------------------------------------------
	{
		auto trav = traverser(imgOut, y1, y2);

		#pragma omp parallel for
		for (auto sub_trav : trav) {
			sub_trav.for_each([&](auto state) {
				imgOut[state] = c2 * (y1[state] + y2[state]);
			});
		}
	}
#pragma endscop
}

