// computation kernel
// imgIn, imgOut, y1, y2: i x j
//
// Optimizations w.r.t. the original version:
//  * common sub‑expressions in the coefficient setup are hoisted
//  * the two “combine” passes are fused into the corresponding
//    anti‑causal passes to reduce memory traffic
//  * inner loops use cached values/references to minimize repeated
//    bag lookups and arithmetic
//  * reverse traversals are implemented by walking the Noarr state
//    backwards using `neighbor` instead of recomputing indices
[[gnu::flatten, gnu::noinline]]
void kernel_deriche(num_t alpha, auto imgIn, auto imgOut, auto y1, auto y2) {
	using namespace noarr;

	num_t k;
	num_t a1, a2, a3, a4, a5, a6, a7, a8;
	num_t b1, b2, c1, c2;

#pragma scop
	// Coefficient setup (same math as original, but with manual CSE)
	const num_t one  = SCALAR_VAL(1.0);
	const num_t two  = SCALAR_VAL(2.0);
	const num_t zero = SCALAR_VAL(0.0);

	const num_t exp_neg_alpha  = EXP_FUN(-alpha);
	const num_t exp_pos_2alpha = EXP_FUN(two * alpha);
	const num_t exp_neg_2alpha = EXP_FUN(-two * alpha);

	k = (one - exp_neg_alpha) * (one - exp_neg_alpha) /
	    (one + two * alpha * exp_neg_alpha - exp_pos_2alpha);

	const num_t k_exp_neg_alpha = k * exp_neg_alpha;

	a1 = a5 = k;
	a2 = a6 = k_exp_neg_alpha * (alpha - one);
	a3 = a7 = k_exp_neg_alpha * (alpha + one);
	a4 = a8 = -k * exp_neg_2alpha;

	b1 = POW_FUN(two, -alpha);
	b2 = -exp_neg_2alpha;
	c1 = c2 = one;

	// lengths used for reverse traversals
	const std::size_t w_len = imgIn | get_length<'i'>();
	const std::size_t h_len = imgIn | get_length<'j'>();

	// ------------------------------------------------------------------
	// 1st pass: causal filter along j, for each i (forward j)
	// for (i=0; i<W; i++)
	//   ym1=0; ym2=0; xm1=0;
	//   for (j=0; j<H; j++)
	//     y1[i][j] = a1*imgIn[i][j] + a2*xm1 + b1*ym1 + b2*ym2; ...
	// ------------------------------------------------------------------
	traverser(y1, imgIn).template for_dims<'i'>([&](auto row_trav) {
		num_t ym1 = zero;
		num_t ym2 = zero;
		num_t xm1 = zero;

		// Only 'j' varies here; 'i' is fixed by row_trav.
		row_trav.for_each([&](auto state) {
			const num_t x_cur = imgIn[state];
			const num_t y_cur = a1 * x_cur + a2 * xm1 + b1 * ym1 + b2 * ym2;

			y1[state] = y_cur;

			xm1 = x_cur;
			ym2 = ym1;
			ym1 = y_cur;
		});
	});

	// ------------------------------------------------------------------
	// 2nd pass: anti-causal filter along j, for each i (reverse j)
	// Original C: j from H-1 down to 0
	// Here we traverse j in 0..H-1 and walk a separate state backwards:
	//   r = 0..H-1, j = H-1-r
	//
	// This pass is fused with the vertical combine:
	//   imgOut[i][j] = c1 * (y1[i][j] + y2[i][j]);
	// ------------------------------------------------------------------
	traverser(y2, imgIn, y1, imgOut).template for_dims<'i'>([&](auto row_trav) {
		num_t yp1 = zero;
		num_t yp2 = zero;
		num_t xp1 = zero;
		num_t xp2 = zero;

		// Start from j = H-1 for this row.
		auto rev_state = row_trav.state() + idx<'j'>(h_len - 1);

		row_trav.for_each([&](auto /*unused_state*/) {
			// Compute anti-causal output at current reversed position
			const num_t y_cur = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;
			y2[rev_state] = y_cur;

			// Vertical combine (uses completed first pass y1)
			imgOut[rev_state] = c1 * (y1[rev_state] + y_cur);

			// Update recurrence state using the original input sample
			const num_t x_cur = imgIn[rev_state];
			xp2 = xp1;
			xp1 = x_cur;
			yp2 = yp1;
			yp1 = y_cur;

			// Move to previous column (j--)
			rev_state = neighbor<'j'>(rev_state, -1);
		});
	});

	// ------------------------------------------------------------------
	// 3rd pass: causal filter along i, for each j (forward i)
	// for (j=0; j<H; j++)
	//   tm1=0; ym1=0; ym2=0;
	//   for (i=0; i<W; i++)
	//     y1[i][j] = a5*imgOut[i][j] + a6*tm1 + b1*ym1 + b2*ym2; ...
	// ------------------------------------------------------------------
	traverser(y1, imgOut).template for_dims<'j'>([&](auto col_trav) {
		num_t tm1 = zero;
		num_t ym1 = zero;
		num_t ym2 = zero;

		// Only 'i' varies here; 'j' is fixed by col_trav.
		col_trav.for_each([&](auto state) {
			const num_t x_cur = imgOut[state];
			const num_t y_cur = a5 * x_cur + a6 * tm1 + b1 * ym1 + b2 * ym2;

			y1[state] = y_cur;

			tm1 = x_cur;
			ym2 = ym1;
			ym1 = y_cur;
		});
	});

	// ------------------------------------------------------------------
	// 4th pass: anti-causal filter along i, for each j (reverse i)
	// Original C: i from W-1 down to 0
	// We again traverse i in 0..W-1 and walk a separate state backwards:
	//   r = 0..W-1, i = W-1-r
	//
	// This pass is fused with the final combine:
	//   imgOut[i][j] = c2 * (y1[i][j] + y2[i][j]);
	// ------------------------------------------------------------------
	traverser(y2, imgOut, y1).template for_dims<'j'>([&](auto col_trav) {
		num_t tp1 = zero;
		num_t tp2 = zero;
		num_t yp1 = zero;
		num_t yp2 = zero;

		// Start from i = W-1 for this column.
		auto rev_state = col_trav.state() + idx<'i'>(w_len - 1);

		col_trav.for_each([&](auto /*unused_state*/) {
			// Compute anti-causal output at current reversed position
			const num_t y_cur = a7 * tp1 + a8 * tp2 + b1 * yp1 + b2 * yp2;
			y2[rev_state] = y_cur;

			// Read vertically-filtered value before overwriting imgOut
			const num_t x_cur = imgOut[rev_state];

			// Update recurrence state
			tp2 = tp1;
			tp1 = x_cur;
			yp2 = yp1;
			yp1 = y_cur;

			// Final combine for this pixel
			imgOut[rev_state] = c2 * (y1[rev_state] + y_cur);

			// Move to previous row (i--)
			rev_state = neighbor<'i'>(rev_state, -1);
		});
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t w = W;
	std::size_t h = H;

	// parameter
	num_t alpha;

	// lengths shared by all images
	auto set_lengths =
		noarr::set_length<'i'>(w) ^
		noarr::set_length<'j'>(h);

	// images: i x j
	auto imgIn  = noarr::bag(noarr::scalar<num_t>() ^ tuning.img_layout ^ set_lengths);
	auto imgOut = noarr::bag(noarr::scalar<num_t>() ^ tuning.img_layout ^ set_lengths);
	auto y1     = noarr::bag(noarr::scalar<num_t>() ^ tuning.img_layout ^ set_lengths);
	auto y2     = noarr::bag(noarr::scalar<num_t>() ^ tuning.img_layout ^ set_lengths);

	// initialize data
	init_array(alpha, imgIn.get_ref(), imgOut.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_deriche(alpha, imgIn.get_ref(), imgOut.get_ref(), y1.get_ref(), y2.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (acts as DCE prevention)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, imgOut.get_ref() ^ noarr::hoist<'i'>());
