	num_t k;
	num_t a1, a2, a3, a4, a5, a6, a7, a8;
	num_t b1, b2, c1, c2;

#pragma scop
	// ----- coefficient setup (unchanged mathematically from C version) -----
	// Precompute exponentials to avoid redundant EXP_FUN calls.
	const num_t one = SCALAR_VAL(1.0);
	const num_t two = SCALAR_VAL(2.0);

	const num_t ea  = EXP_FUN(-alpha);
	const num_t e2a = EXP_FUN(-two * alpha); // = exp(-2*alpha)

	const num_t one_minus_ea = one - ea;
	const num_t denom        = one + two * alpha * ea - e2a;

	k  = (one_minus_ea * one_minus_ea) / denom;
	a1 = a5 = k;
	a2 = a6 = k * ea * (alpha - one);
	a3 = a7 = k * ea * (alpha + one);
	a4 = a8 = -k * e2a;
	b1 = POW_FUN(two, -alpha);
	b2 = -e2a;
	c1 = c2 = one;

	// lengths used for reverse traversals and parallelization thresholds
	const std::size_t w_len = imgIn | get_length<'i'>(); // W
	const std::size_t h_len = imgIn | get_length<'j'>(); // H

	// ----------------------------------------------------------------------
	// 1st pass: causal filter along j, for each i (forward j)
	//   for (i=0; i<W; i++)
	//     ym1=0; ym2=0; xm1=0;
	//     for (j=0; j<H; j++)
	//       y1[i][j] = a1*imgIn[i][j] + a2*xm1 + b1*ym1 + b2*ym2;
	//       xm1 = imgIn[i][j]; ym2 = ym1; ym1 = y1[i][j];
