	// a traverser with 'i' fixed and walks all 'j' for that row.
	// Access along 'j' is contiguous in memory (good locality).
	auto trav_rows_y1 = traverser(y1, imgIn);

#pragma omp parallel for if (w_len >= tuning.min_parallel_rows)
	for (auto row_trav : trav_rows_y1) {
		num_t ym1 = SCALAR_VAL(0.0);
		num_t ym2 = SCALAR_VAL(0.0);
		num_t xm1 = SCALAR_VAL(0.0);

