			const num_t x_cur = imgIn[state];
			const num_t y_cur = a1 * x_cur + a2 * xm1 + b1 * ym1 + b2 * ym2;

			y1[state] = y_cur;

			xm1 = x_cur;
			ym2 = ym1;
			ym1 = y_cur;
		});
	}

