	// Original C: j from H-1 down to 0.
	// Here we still iterate j in 0..H-1 for better traversal API usage,
	// but maintain our own reverse index j_rev = H-1, H-2, ..., 0.
	// This preserves exact recurrence semantics while keeping the loops
	// expressed purely via Noarr traversers.
	auto trav_rows_y2 = traverser(y2, imgIn);

#pragma omp parallel for if (w_len >= tuning.min_parallel_rows)
	for (auto row_trav : trav_rows_y2) {
		num_t yp1 = SCALAR_VAL(0.0);
		num_t yp2 = SCALAR_VAL(0.0);
		num_t xp1 = SCALAR_VAL(0.0);
		num_t xp2 = SCALAR_VAL(0.0);

		std::size_t j_rev = h_len - 1; // maps current iteration to reversed j

		row_trav.for_each([&](auto state) {
			const std::size_t i_idx = get_index<'i'>(state);
			const auto        rev_state = idx<'i', 'j'>(i_idx, j_rev);

			const num_t y_cur = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;
			y2[rev_state] = y_cur;

			xp2 = xp1;
			xp1 = imgIn[rev_state];
			yp2 = yp1;
			yp1 = y_cur;

			--j_rev;
		});
	}

