	auto trav_vert_combine = traverser(imgOut, y1, y2);

#pragma omp parallel for if (w_len * h_len >= tuning.min_parallel_rows * tuning.min_parallel_cols)
	for (auto block_trav : trav_vert_combine) {
		block_trav.for_each([&](auto state) {
			imgOut[state] = c1 * (y1[state] + y2[state]);
		});
	}

	// ----------------------------------------------------------------------
	// 3rd pass: causal filter along i, for each j (forward i)
	//   for (j=0; j<H; j++)
	//     tm1=0; ym1=0; ym2=0;
	//     for (i=0; i<W; i++)
	//       y1[i][j] = a5*imgOut[i][j] + a6*tm1 + b1*ym1 + b2*ym2;
	//       tm1 = imgOut[i][j]; ym2 = ym1; ym1 = y1[i][j];
