	for (auto col_trav : trav_cols_y1) {
		num_t tm1 = SCALAR_VAL(0.0);
		num_t ym1 = SCALAR_VAL(0.0);
		num_t ym2 = SCALAR_VAL(0.0);

		col_trav.for_each([&](auto state) {
			const num_t x_cur = imgOut[state];
			const num_t y_cur = a5 * x_cur + a6 * tm1 + b1 * ym1 + b2 * ym2;

			y1[state] = y_cur;

			tm1 = x_cur;
			ym2 = ym1;
			ym1 = y_cur;
		});
	}

	// ----------------------------------------------------------------------
	// 4th pass: anti-causal filter along i, for each j (reverse i)
	// Original C: i from W-1 down to 0.
	// Again we walk i in 0..W-1 with a separate reverse index i_rev.
	auto trav_cols_y2 = traverser(y2, imgOut).order(hoist<'j'>());

#pragma omp parallel for if (h_len >= tuning.min_parallel_cols)
	for (auto col_trav : trav_cols_y2) {
		num_t tp1 = SCALAR_VAL(0.0);
		num_t tp2 = SCALAR_VAL(0.0);
		num_t yp1 = SCALAR_VAL(0.0);
		num_t yp2 = SCALAR_VAL(0.0);

		std::size_t i_rev = w_len - 1;

		// Column index is fixed in this traverser; read it once.
		const auto col_state = col_trav.state();
		const std::size_t j_idx = get_index<'j'>(col_state);

		col_trav.for_each([&](auto /*state*/) {
			const auto rev_state = idx<'i', 'j'>(i_rev, j_idx);

			const num_t y_cur = a7 * tp1 + a8 * tp2 + b1 * yp1 + b2 * yp2;
