	const num_t a6 = a2;
	const num_t a7 = a3;
	const num_t a8 = a4;

	const num_t b1 = POW_FUN(SCALAR_VAL(2.0), -alpha);
	const num_t b2 = -ea2;
	const num_t c1 = SCALAR_VAL(1.0);
	const num_t c2 = SCALAR_VAL(1.0);

	// lengths used for reverse traversals
	const std::size_t w_len = imgIn | get_length<'i'>(); // width  (dimension 'i')
	const std::size_t h_len = imgIn | get_length<'j'>(); // height (dimension 'j')

	// ------------------------------------------------------------------
	// 1st pass: causal filter along j, for each i (forward j)
	//
	// for (i = 0; i < W; i++) {
	//   ym1 = ym2 = xm1 = 0;
	//   for (j = 0; j < H; j++) {
	//     y1[i][j] = a1 * imgIn[i][j] + a2 * xm1 + b1 * ym1 + b2 * ym2;
	//     xm1 = imgIn[i][j];
	//     ym2 = ym1;
	//     ym1 = y1[i][j];
	//   }
	// }
	//
	// Parallelised across rows i; inner loop over j uses contiguous accesses.
	// ------------------------------------------------------------------
	{
		auto trav_rows = traverser(y1, imgIn).order(hoist<'i'>());

#pragma omp parallel for schedule(static)
		for (auto row_trav : trav_rows) {
			num_t ym1 = SCALAR_VAL(0.0);
			num_t ym2 = SCALAR_VAL(0.0);
			num_t xm1 = SCALAR_VAL(0.0);

			row_trav.template for_each<'j'>([&](auto state) {
				const num_t in = imgIn[state];
				const num_t y  = a1 * in + a2 * xm1 + b1 * ym1 + b2 * ym2;

				y1[state] = y;

				xm1 = in;
				ym2 = ym1;
				ym1 = y;
			});
		}
	}

	// ------------------------------------------------------------------
	// 2nd pass: anti-causal filter along j, for each i (reverse j)
	// + combine horizontal passes:
	//
	// Original C (anti-causal only):
	//   for (i = 0; i < W; i++) {
	//     yp1 = yp2 = xp1 = xp2 = 0;
	//     for (j = H-1; j >= 0; j--) {
	//       y2[i][j] = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;
	//       xp2 = xp1;
	//       xp1 = imgIn[i][j];
	//       yp2 = yp1;
	//       yp1 = y2[i][j];
	//     }
	//   }
	//
	// Original combination (separate pass):
	//   imgOut[i][j] = c1 * (y1[i][j] + y2[i][j]);
	//
	// We fuse the combination: as soon as we compute y2[i][j], we store it
	// and immediately write imgOut[i][j]. This removes an extra full-image
	// traversal while preserving semantics and y2 contents.
	// ------------------------------------------------------------------
	{
		auto trav_rows = traverser(y2, imgIn, y1, imgOut).order(hoist<'i'>());

#pragma omp parallel for schedule(static)
		for (auto row_trav : trav_rows) {
			auto base_state = row_trav.state(); // contains fixed 'i'

			num_t yp1 = SCALAR_VAL(0.0);
			num_t yp2 = SCALAR_VAL(0.0);
			num_t xp1 = SCALAR_VAL(0.0);
			num_t xp2 = SCALAR_VAL(0.0);

			// Traverse 'j' in forward order via for_each, but map each
			// iteration to a decreasing logical index j_rev = H-1, H-2, ...
			std::size_t j_rev = h_len;

			row_trav.template for_each<'j'>([&](auto /*unused*/) {
				--j_rev; // first iteration uses H-1

				auto rev_state = base_state + idx<'j'>(j_rev);

				const num_t y2_val = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;
				y2[rev_state] = y2_val;

				const num_t y1_val = y1[rev_state];
				imgOut[rev_state] = c1 * (y1_val + y2_val);

				xp2 = xp1;
				xp1 = imgIn[rev_state];
				yp2 = yp1;
				yp1 = y2_val;
			});
		}
	}

	// ------------------------------------------------------------------
	// 3rd pass: causal filter along i, for each j (forward i)
	//
	// for (j = 0; j < H; j++) {
	//   tm1 = ym1 = ym2 = 0;
	//   for (i = 0; i < W; i++) {
	//     y1[i][j] = a5 * imgOut[i][j] + a6 * tm1 + b1 * ym1 + b2 * ym2;
	//     tm1 = imgOut[i][j];
	//     ym2 = ym1;
	//     ym1 = y1[i][j];
	//   }
	// }
	//
	// Parallelised across columns j; inner loop over i walks one column
	// (strided access is inherent to the algorithm).
	// ------------------------------------------------------------------
	{
		auto trav_cols = traverser(y1, imgOut).order(hoist<'j'>());

#pragma omp parallel for schedule(static)
		for (auto col_trav : trav_cols) {
			num_t tm1 = SCALAR_VAL(0.0);
			num_t ym1 = SCALAR_VAL(0.0);
			num_t ym2 = SCALAR_VAL(0.0);

			col_trav.template for_each<'i'>([&](auto state) {
				const num_t in = imgOut[state];
				const num_t y  = a5 * in + a6 * tm1 + b1 * ym1 + b2 * ym2;

				y1[state] = y;

				tm1 = in;
				ym2 = ym1;
				ym1 = y;
			});
		}
	}

	// ------------------------------------------------------------------
	// 4th pass: anti-causal filter along i, for each j (reverse i)
	// + final combine:
	//
	// Original C (anti-causal only):
	//   for (j = 0; j < H; j++) {
	//     tp1 = tp2 = yp1 = yp2 = 0;
	//     for (i = W-1; i >= 0; i--) {
	//       y2[i][j] = a7 * tp1 + a8 * tp2 + b1 * yp1 + b2 * yp2;
	//       tp2 = tp1;
	//       tp1 = imgOut[i][j];
	//       yp2 = yp1;
	//       yp1 = y2[i][j];
	//     }
	//   }
	//
	// Original final combination (separate pass):
	//   imgOut[i][j] = c2 * (y1[i][j] + y2[i][j]);
	//
	// We fuse the final combine with this anti-causal pass. To keep
	// semantics identical and preserve y2, we:
	//   - read the original horizontally/vertically-causal imgOut[i][j]
	//     into a local 'in' before overwriting it,
	//   - compute y2[i][j] and store it,
	//   - immediately compute the final value using y1 and y2 and
	//     write it back to imgOut[i][j],
	//   - update the recurrence using 'in'.
	// ------------------------------------------------------------------
	{
		auto trav_cols = traverser(y2, imgOut, y1).order(hoist<'j'>());

#pragma omp parallel for schedule(static)
		for (auto col_trav : trav_cols) {
			auto base_state = col_trav.state(); // contains fixed 'j'

			num_t tp1 = SCALAR_VAL(0.0);
			num_t tp2 = SCALAR_VAL(0.0);
			num_t yp1 = SCALAR_VAL(0.0);
			num_t yp2 = SCALAR_VAL(0.0);

			// Traverse 'i' forward via for_each, but map iterations to
			// i_rev = W-1, W-2, ...
			std::size_t i_rev = w_len;

			col_trav.template for_each<'i'>([&](auto /*unused*/) {
				--i_rev; // first iteration uses W-1

				auto rev_state = base_state + idx<'i'>(i_rev);

				// Read input before overwriting imgOut at this position
				const num_t in     = imgOut[rev_state];
				const num_t y2_val = a7 * tp1 + a8 * tp2 + b1 * yp1 + b2 * yp2;
				y2[rev_state] = y2_val;

				const num_t y1_val  = y1[rev_state];
				const num_t out_val = c2 * (y1_val + y2_val);
				imgOut[rev_state] = out_val;

				tp2 = tp1;
				tp1 = in;
				yp2 = yp1;
				yp1 = y2_val;
			});
		}
	}
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t w = W;
	std::size_t h = H;

	// parameter
	num_t alpha;

	// lengths shared by all images
	auto set_lengths =
		noarr::set_length<'i'>(w) ^
		noarr::set_length<'j'>(h);

	// images: i x j
	auto imgIn  = noarr::bag(noarr::scalar<num_t>() ^ tuning.img_layout ^ set_lengths);
	auto imgOut = noarr::bag(noarr::scalar<num_t>() ^ tuning.img_layout ^ set_lengths);
	auto y1     = noarr::bag(noarr::scalar<num_t>() ^ tuning.img_layout ^ set_lengths);
	auto y2     = noarr::bag(noarr::scalar<num_t>() ^ tuning.img_layout ^ set_lengths);

	// initialize data
	init_array(alpha, imgIn.get_ref(), imgOut.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_deriche(alpha, imgIn.get_ref(), imgOut.get_ref(), y1.get_ref(), y2.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (acts as DCE prevention)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, imgOut.get_ref() ^ noarr::hoist<'i'>());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
